pub const ComponentParser = struct {
    allow_none: bool,
    @"from": ?RelativeComponentParser,

pub fn new(allow_none: bool) ComponentParser {
            return ComponentParser{ .allow_none = allow_none, .@"from" = null };
    }

pub fn parseRelative(self: *ComponentParser, input: *css.Parser, comptime T: type, comptime C: type, comptime func: anytype, args_: anytype) Result(C) {
            if (input.tryParse(css.Parser.expectIdentMatching, .{ "from" }).isOk()) {
                const from_val = (switch (CssColor.parse(input)) {
.result => |vv| vv,
.err => |e| {
return .{ .err = e };
},
});
                return self.parseFrom(from_val, input, T, C, func, args_);
            }
            const args = bun.@"meta".ConcatArgs2(func, input, self, args_);
            return @call(.auto, func, args);
    }

pub fn parseFrom(self: *ComponentParser, from_val: CssColor, input: *css.Parser, comptime T: type, comptime C: type, comptime func: anytype, args_: anytype) Result(C) {
            if ((from_val == .light_dark)) {
                const state = input.state();
                const light = (switch (self.parseFrom((blk: {
                break :blk from_val.light_dark.light.*;

}), input, T, C, func, args_)) {
.result => |vv| vv,
.err => |e| {
return .{ .err = e };
},
});
                _ = input.reset((&state));
                const dark = (switch (self.parseFrom((blk: {
                break :blk from_val.light_dark.dark.*;

}), input, T, C, func, args_)) {
.result => |vv| vv,
.err => |e| {
return .{ .err = e };
},
});
                return .{ .result = C.lightDarkOwned(input.allocator(), light, dark) };
            }
            const opt_from = T.tryFromCssColor((&from_val));
            if ((opt_from == null)) {
                return .{ .err = input.newCustomError(css.ParserError.invalid_value) };
            }
            const new_from = opt_from.?.resolve();
            self.@"from" = RelativeComponentParser.new((&new_from));
            const args = bun.@"meta".ConcatArgs2(func, input, self, args_);
            return @call(.auto, func, args);
    }

pub fn parseNumberOrPercentage(self: ComponentParser, input: *css.Parser) Result(NumberOrPercentage) {
            if ((self.@"from" != null)) {
                if (input.tryParse(RelativeComponentParser.parseNumberOrPercentage, .{ (&self.@"from".?) }).asValue()) |res| {
                    _ = &res;
                    return .{ .result = res };
                }
            }
            if (input.tryParse(CSSNumberFns.parse, .{}).asValue()) |value| {
                _ = &value;
                return .{ .result = NumberOrPercentage{ .number = .{ .value = value } } };
            } else {
                if (input.tryParse(Percentage.parse, .{}).asValue()) |value| {
                    _ = &value;
                    return .{ .result = NumberOrPercentage{ .percentage = .{ .unit_value = value.v } } };
                } else {
                    if (self.allow_none) {
                        if (input.expectIdentMatching("none").asErr()) |e| {
                            _ = &e;
                            return .{ .err = e };
                        }
                        return .{ .result = NumberOrPercentage{ .number = .{ .value = std.math.nan(f32) } } };
                    } else {
                        return .{ .err = input.newCustomError(css.ParserError.invalid_value) };
                    }
                }
            }
    }

