            return oklch.into(conversion_target);
        }
        if ((current.l < EPSILON)) {
            const oklch = OKLCH{ .l = 0.0, .c = 0.0, .h = 0.0, .alpha = current.alpha };
            return oklch.into(conversion_target);
        }
        var min: f32 = 0.0;
