pub fn writeComponents(name: []const u8, a: f32, b: f32, c: f32, alpha: f32, dest: *Printer) PrintErr!void {
        _ = try dest.writeStr(name);
        _ = try dest.writeChar(40);
        if (std.math.isNan(a)) {
            _ = try dest.writeStr("none");
        } else {
            const pct = Percentage{ .v = a };
            _ = try pct.toCss(dest);
        }
        _ = try dest.writeChar(32);
        _ = try writeComponent(b, dest);
        _ = try dest.writeChar(32);
        _ = try writeComponent(c, dest);
        if ((std.math.isNan(alpha) or (@abs((alpha - 1.0)) > std.math.floatEps(f32)))) {
            _ = try dest.delim(47, true);
            _ = try writeComponent(alpha, dest);
        }
        return dest.writeChar(41);
}

pub fn writeComponent(c: f32, dest: *Printer) PrintErr!void {
        if (std.math.isNan(c)) {
            return dest.writeStr("none");
        } else {
            return CSSNumberFns.toCss((&c), dest);
        }
}

